sp_widget.client_script:
api.controller = function($window) {

    var c = this;


    /* =========================================
       DEFAULT TAB
    ========================================= */

    c.activeTab = 'reports';


    /* =========================================
       DEFAULT REPORT FILTER
    ========================================= */

    c.reportFilter = 'all';


    /* =========================================
       WITHDRAW CLAIM STATE
    ========================================= */

    c.withdrawOpen = false;
    c.withdrawClaim = null;
    c.withdrawReason = '';

    c.processing = false;

    c.actionMessage = '';
    c.actionError = false;


    /* =========================================
       CHANGE TAB
    ========================================= */

    c.changeTab = function(tab) {

        c.activeTab = tab;

    };


    /* =========================================
       REPORT FILTER
    ========================================= */

    c.setReportFilter = function(filter) {

        c.reportFilter = filter;

    };


    /* =========================================
       FILTER REPORTS
    ========================================= */

    c.filteredReports = function() {

        var reports = c.data.reports || [];


        if (c.reportFilter === 'all') {

            return reports;

        }


        return reports.filter(function(report) {

            return report.reportType === c.reportFilter;

        });

    };


    /* =========================================
       STATUS CLASS
    ========================================= */

    c.statusClass = function(item) {

        var status =
            (item.statusValue || '')
            .toLowerCase();


        if (status === 'resolved') {

            return 'cm-status-resolved';

        }


        if (
            status === 'active' ||
            status === 'draft'
        ) {

            return 'cm-status-active';

        }


        if (
            status === 'matched' ||
            status === 'claimed'
        ) {

            return 'cm-status-matched';

        }


        return 'cm-status-other';

    };


    /* =========================================
       OPEN WITHDRAW MODAL
    ========================================= */

    c.openWithdraw = function(activity) {

        if (
            !activity ||
            !activity.claimId ||
            !activity.canWithdraw
        ) {

            return;

        }


        c.withdrawClaim = activity;

        c.withdrawReason = '';

        c.actionMessage = '';
        c.actionError = false;

        c.withdrawOpen = true;

    };


    /* =========================================
       CLOSE WITHDRAW MODAL
    ========================================= */

    c.closeWithdraw = function() {

        if (c.processing) {

            return;

        }


        c.withdrawOpen = false;

        c.withdrawClaim = null;

        c.withdrawReason = '';

    };


    /* =========================================
       CONFIRM WITHDRAWAL
    ========================================= */

    c.confirmWithdraw = function() {

        if (
            c.processing ||
            !c.withdrawClaim ||
            !c.withdrawClaim.claimId
        ) {

            return;

        }


        c.processing = true;

        c.actionMessage = '';
        c.actionError = false;


        c.server.get({

            action: 'withdrawClaim',

            claim_id:
                c.withdrawClaim.claimId,

            match_id:
                c.withdrawClaim.matchId,

            reason:
                (c.withdrawReason || '')
                .substring(
                    0,
                    500
                )

        }).then(

            function(response) {

                c.processing = false;


                if (
                    !response ||
                    !response.data
                ) {

                    c.actionError = true;

                    c.actionMessage =
                        'The withdrawal could not be completed.';

                    return;

                }


                if (!response.data.success) {

                    c.actionError = true;

                    c.actionMessage =
                        response.data.message ||
                        'The withdrawal could not be completed.';

                    return;

                }


                c.withdrawOpen = false;

                c.withdrawClaim = null;

                c.withdrawReason = '';

                c.actionError = false;

                c.actionMessage =
                    response.data.message ||
                    'Your claim has been withdrawn.';


                /*
                 * Reload dashboard after successful
                 * withdrawal.
                 */

                $window.setTimeout(
                    function() {

                        $window.location.reload();

                    },
                    700
                );

            },

            function() {

                c.processing = false;

                c.actionError = true;

                c.actionMessage =
                    'The withdrawal could not be completed. Please try again.';

            }

        );

    };

};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH USER DASHBOARD
   WEBSITE + NOW MOBILE APP
   FULL-BLEED SAFE VERSION
========================================================== */

.cm-dashboard {
  position: relative;
  display: block;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  padding: 54px 20px 90px;

  background:
    linear-gradient(
      180deg,
      #FBF8EF 0%,
      #F5F7F0 100%
    ) !important;

  box-shadow:
    0 -60px 0 #FBF8EF,
    0 60px 0 #F5F7F0;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  color: #102E34;

  box-sizing: border-box !important;

  overflow-x: hidden;
}


.cm-dashboard,
.cm-dashboard *,
.cm-dashboard *::before,
.cm-dashboard *::after {
  box-sizing: border-box;
}


.cm-dashboard-container {
  position: relative;

  width: 100%;
  max-width: 1240px;

  margin: 0 auto;
}


/* ==========================================================
   HEADER
========================================================== */

.cm-dashboard-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 30px;

  margin-bottom: 36px;
}


.cm-dashboard-eyebrow {
  display: inline-flex;

  padding: 8px 15px;
  margin-bottom: 14px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 12px;
  font-weight: 800;
}


.cm-dashboard-header h1 {
  margin: 0 0 7px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 38px;
  font-weight: 700;

  letter-spacing: -1px;
}


.cm-dashboard-header p {
  margin: 0;

  color: #617477;

  font-size: 15px;
}


.cm-header-actions {
  display: flex;

  gap: 10px;

  flex-shrink: 0;
}


.cm-action-btn {
  padding: 12px 19px;

  border-radius: 999px;

  font-size: 13px;
  font-weight: 800;

  text-decoration: none !important;
}


.cm-action-primary {
  background: #104E45;

  color: #FFFFFF !important;
}


.cm-action-secondary {
  border: 1.5px solid #D2DED8;

  background: #FFFFFF;

  color: #104E45 !important;
}


/* ==========================================================
   DASHBOARD SHELL
========================================================== */

.cm-dashboard-shell {
  display: grid;

  grid-template-columns:
    245px minmax(0,1fr);

  gap: 30px;
}


/* ==========================================================
   SIDEBAR
========================================================== */

.cm-dashboard-sidebar {
  height: fit-content;

  padding: 22px 17px;

  border: 1px solid #D2DED8;

  border-radius: 23px;

  background: #FFFFFF;

  box-shadow:
    0 6px 20px rgba(16,78,69,.06);
}


/* USER */

.cm-user-card {
  display: flex;
  align-items: center;

  gap: 11px;

  padding:
    4px
    3px
    19px;

  margin-bottom: 13px;

  border-bottom:
    1px solid #EDF2EE;
}


.cm-user-avatar {
  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  background: #EDF5E9;

  color: #15564B;

  font-size: 13px;
  font-weight: 800;
}


.cm-user-info {
  min-width: 0;

  display: flex;
  flex-direction: column;
}


.cm-user-info strong {
  overflow: hidden;

  color: #102E34;

  font-size: 13px;

  text-overflow: ellipsis;
  white-space: nowrap;
}


.cm-user-info span {
  margin-top: 2px;

  color: #000000;

  font-size: 12px;
}


/* NAV */

.cm-dashboard-nav {
  display: flex;
  flex-direction: column;

  gap: 4px;
}


.cm-dashboard-nav button,
.cm-dashboard-nav a {
  width: 100%;

  padding: 11px 12px;

  display: flex;
  align-items: center;

  gap: 9px;

  border: 0;

  border-radius: 12px;

  background: transparent;

  color: #687A7E;

  font-family: inherit;

  font-size: 12px;
  font-weight: 700;

  text-align: left;

  text-decoration: none !important;

  cursor: pointer;

  transition:
    background .2s ease,
    color .2s ease;
}


.cm-dashboard-nav button:hover,
.cm-dashboard-nav a:hover,
.cm-dashboard-nav button.active {
  background: #EDF5E9;

  color: #15564B;
}


.cm-dashboard-nav svg {
  width: 18px;
  height: 18px;

  flex-shrink: 0;
}


/* ==========================================================
   STATS
========================================================== */

.cm-dashboard-stats {
  display: grid;

  grid-template-columns:
    repeat(4,minmax(0,1fr));

  gap: 14px;

  margin-bottom: 35px;
}


.cm-stat-card {
  min-width: 0;

  padding: 17px;

  display: flex;
  align-items: center;

  gap: 12px;

  border: 1px solid #D2DED8;

  border-radius: 19px;

  background: #FFFFFF;

  box-shadow:
    0 4px 15px rgba(16,78,69,.05);
}


.cm-stat-icon {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 14px;
}


.cm-stat-icon svg {
  width: 21px;
  height: 21px;
}


.cm-stat-lost {
  background: #FBEAE7;
  color: #B5502F;
}


.cm-stat-found {
  background: #EDF5E9;
  color: #15564B;
}


.cm-stat-match {
  background: #E9F1FF;
  color: #2B5FA8;
}


.cm-stat-resolved {
  background: #E4F4EA;
  color: #168C70;
}


.cm-stat-card > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;
}


.cm-stat-card strong {
  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 22px;
}


.cm-stat-card span {
  color: #000000;

  font-size: 12px;
}


/* ==========================================================
   SECTION HEADER
========================================================== */

.cm-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 20px;

  margin-bottom: 18px;
}


.cm-section-header h2 {
  margin: 0 0 3px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 22px;
}


.cm-section-header p {
  margin: 0;

  color: #78878A;

  font-size: 12px;
}


.cm-explore-link {
  color: #168C70 !important;

  font-size: 12px;
  font-weight: 800;

  text-decoration: none !important;
}


/* ==========================================================
   FILTER
========================================================== */

.cm-report-filter {
  display: flex;

  gap: 8px;

  margin-bottom: 20px;
}


.cm-report-filter button {
  padding: 8px 16px;

  border: 1.5px solid #D2DED8;

  border-radius: 999px;

  background: #FFFFFF;

  color: #617477;

  font-size: 11px;
  font-weight: 800;

  cursor: pointer;
}


.cm-report-filter button.active {
  border-color: #104E45;

  background: #104E45;

  color: #FFFFFF;
}


/* ==========================================================
   REPORT GRID
========================================================== */

.cm-report-grid {
  display: grid;

  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap: 18px;
}


/* ==========================================================
   REPORT CARD
========================================================== */

.cm-report-item {
  overflow: hidden;

  border: 1px solid #D2DED8;

  border-radius: 21px;

  background: #FFFFFF;

  box-shadow:
    0 5px 17px rgba(16,78,69,.05);

  transition:
    transform .2s ease,
    box-shadow .2s ease;
}


.cm-report-item:hover {
  transform: translateY(-3px);

  box-shadow:
    0 11px 25px rgba(16,78,69,.09);
}


/* MEDIA */

.cm-report-media {
  position: relative;

  height: 145px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  background:
    linear-gradient(
      145deg,
      #EDF5E9,
      #E3F0E5
    );

  color: #15564B;
}


.cm-report-media.lost {
  background:
    linear-gradient(
      145deg,
      #F9EEE8,
      #F6E5DF
    );

  color: #A65A41;
}


/* ==========================================================
   REPORT CARD IMAGE
   STEP 7
========================================================== */

.cm-report-image {
  position: absolute;

  inset: 0;

  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;
  object-position: center;

  z-index: 1;
}


.cm-report-media > svg {
  position: relative;

  width: 52px;
  height: 52px;

  z-index: 2;
}


.cm-report-type {
  position: absolute;

  top: 11px;
  left: 11px;

  padding: 5px 11px;

  border-radius: 999px;

  background: #FFFFFF;

  font-size: 10px;
  font-weight: 800;

  z-index: 3;
}


.cm-report-type.lost {
  color: #000000;
}


.cm-report-type.found {
  color: #15564B;
}


/* BODY */

.cm-report-body {
  padding: 17px;
}


.cm-report-body h3 {
  min-height: 39px;

  margin: 0 0 8px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 15px;
  line-height: 1.3;
}


.cm-report-meta {
  display: flex;
  flex-wrap: wrap;

  gap: 7px 12px;

  color: #000000;

  font-size: 10px;
}


.cm-report-status-row {
  display: flex;
  flex-wrap: wrap;

  gap: 6px;

  margin-top: 14px;
}


.cm-status-badge,
.cm-match-badge {
  padding: 5px 9px;

  border-radius: 999px;

  font-size: 9px;
  font-weight: 800;
}


.cm-status-active {
  background: #FDF3DC;

  color: #8A6719;
}


.cm-status-resolved {
  background: #E4F4EA;

  color: #168C70;
}


.cm-status-matched {
  background: #EDF5E9;

  color: #15564B;
}


.cm-status-other {
  background: #EDF2EE;

  color: #617477;
}


/* SMALL STRONG / POTENTIAL BADGE - ORIGINAL COLOR */

.cm-match-badge {
  background: #E9F1FF;

  color: #2B5FA8;
}


/* ==========================================================
   BEST MATCH
========================================================== */

.cm-best-match {
  margin-top: 13px;

  padding: 10px 12px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border-radius: 12px;

  background: #F5F8F3;
}


/* STRONG TEXT LEFT OF PERCENTAGE - BLACK */

.cm-best-match span {
  color: #000000;

  font-size: 9px;
  font-weight: 700;
}


.cm-best-match strong {
  color: #168C70;

  font-size: 13px;
  font-weight: 900;
}


/* FOOTER */

.cm-report-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 10px;

  margin-top: 15px;
  padding-top: 13px;

  border-top: 1px solid #EDF2EE;
}


.cm-report-number {
  color: #000000;

  font-size: 9px;
  font-weight: 700;
}


.cm-report-footer a {
  color: #104E45 !important;

  font-size: 10px;
  font-weight: 800;

  text-decoration: none !important;
}


.cm-report-footer .cm-match-action {
  padding: 6px 10px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #168C70 !important;
}


/* ==========================================================
   MATCH ACTIVITY
========================================================== */

.cm-activity-list {
  position: relative;

  display: flex;
  flex-direction: column;

  gap: 14px;
}


.cm-activity-card {
  display: grid;

  grid-template-columns:
    32px 1fr;

  gap: 12px;

  padding: 18px;

  border: 1px solid #D2DED8;

  border-radius: 18px;

  background: #FFFFFF;
}


.cm-activity-marker {
  position: relative;

  display: flex;
  justify-content: center;
}


.cm-activity-marker span {
  width: 14px;
  height: 14px;

  margin-top: 4px;

  border: 3px solid #DFF0E5;

  border-radius: 50%;

  background: #249D78;
}


.cm-activity-content {
  min-width: 0;
}


.cm-activity-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 14px;
}


.cm-activity-top h3 {
  margin: 0 0 3px;

  color: #104E45;

  font-size: 14px;
}


.cm-activity-top p {
  margin: 0;

  color: #718185;

  font-size: 11px;
}


.cm-activity-top > span {
  flex-shrink: 0;

  color: #8A979A;

  font-size: 10px;
}


.cm-activity-content > p {
  margin: 9px 0 0;

  color: #617477;

  font-size: 10px;
}


.cm-activity-match-info {
  margin-top: 11px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 10px;
}


.cm-activity-match-info span {
  color: #506267;

  font-size: 9px;
  font-weight: 800;
}


.cm-activity-match-info strong {
  color: #168C70;

  font-size: 13px;
  font-weight: 900;
}


.cm-activity-progress {
  height: 6px;

  margin: 13px 0 11px;

  overflow: hidden;

  border-radius: 999px;

  background: #EDF2EE;
}


.cm-progress-fill {
  height: 100%;

  border-radius: inherit;

  background: #249D78;
}


.cm-activity-content > a {
  color: #168C70 !important;

  font-size: 10px;
  font-weight: 800;

  text-decoration: none !important;
}


/* ==========================================================
   EMPTY STATE
========================================================== */

.cm-empty {
  padding: 55px 20px;

  text-align: center;
}


.cm-empty-icon {
  width: 65px;
  height: 65px;

  margin: 0 auto 15px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 20px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-empty-icon svg {
  width: 29px;
  height: 29px;
}


.cm-empty h3 {
  margin: 0 0 6px;

  color: #104E45;

  font-size: 18px;
}


.cm-empty p {
  max-width: 390px;

  margin: 0 auto 16px;

  color: #718185;

  font-size: 12px;
}


.cm-empty > a {
  display: inline-flex;

  padding: 10px 17px;

  border-radius: 999px;

  background: #104E45;

  color: #FFFFFF !important;

  font-size: 11px;
  font-weight: 800;

  text-decoration: none !important;
}


/* ==========================================================
   TABLET
========================================================== */

@media (max-width: 1050px) {

  .cm-report-grid {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }


  .cm-dashboard-stats {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }

}


/* ==========================================================
   MOBILE
========================================================== */

@media (max-width: 760px) {

  .cm-dashboard {
    min-height: 100svh;

    padding:
      38px
      16px
      70px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F5F7F0;
  }


  .cm-dashboard-header {
    align-items: flex-start;

    flex-direction: column;
  }


  .cm-dashboard-header h1 {
    font-size: 30px;
  }


  .cm-header-actions {
    width: 100%;
  }


  .cm-header-actions a {
    flex: 1;

    text-align: center;
  }


  .cm-dashboard-shell {
    grid-template-columns:
      1fr;
  }


  .cm-dashboard-sidebar {
    padding: 13px;
  }


  .cm-user-card {
    display: none;
  }


  .cm-dashboard-nav {
    display: grid;

    grid-template-columns:
      1fr 1fr;
  }


  .cm-dashboard-nav button,
  .cm-dashboard-nav a {
    justify-content: center;
  }


  .cm-report-grid {
    grid-template-columns:
      1fr;
  }

}


/* ==========================================================
   SMALL MOBILE
========================================================== */

@media (max-width: 480px) {

  .cm-dashboard {
    padding:
      34px
      12px
      65px;
  }


  .cm-dashboard-stats {
    gap: 9px;
  }


  .cm-stat-card {
    padding: 13px;

    gap: 9px;
  }


  .cm-stat-icon {
    width: 36px;

    height: 36px;
  }


  .cm-stat-card strong {
    font-size: 19px;
  }


  .cm-stat-card span {
    font-size: 10px;
  }


  .cm-dashboard-nav button,
  .cm-dashboard-nav a {
    padding:
      10px
      6px;

    font-size: 10px;
  }


  .cm-section-header {
    align-items: flex-start;

    flex-direction: column;
  }


  .cm-report-media {
    height: 135px;
  }

}


/* ==========================================================
   CAMPUSMATCH CLAIM WITHDRAWAL
========================================================== */


/* ==========================================================
   DASHBOARD ACTION MESSAGE
========================================================== */

.cm-dashboard-message {
  margin-bottom: 18px;

  padding: 12px 15px;

  border: 1px solid #CDE5D7;
  border-radius: 13px;

  background: #E4F4EA;

  color: #14765C;

  font-size: 11px;
  font-weight: 700;
}


.cm-dashboard-message.error {
  border-color: #F2D4CC;

  background: #FBEAE7;

  color: #A44832;
}


/* ==========================================================
   CLAIM STATUS INSIDE MATCH ACTIVITY
========================================================== */

.cm-claim-status-row {
  margin-top: 12px;

  padding: 9px 12px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 12px;

  border-radius: 11px;

  background: #F5F8F3;
}


.cm-claim-status-row span {
  color: #718185;

  font-size: 9px;
  font-weight: 700;
}


.cm-claim-status-row strong {
  color: #104E45;

  font-size: 10px;
  font-weight: 800;
}


/* ==========================================================
   MATCH ACTIVITY ACTIONS
========================================================== */

.cm-activity-actions {
  margin-top: 12px;

  display: flex;
  align-items: center;

  gap: 9px;

  flex-wrap: wrap;
}


.cm-activity-actions > a {
  display: inline-flex;
  align-items: center;

  min-height: 32px;

  padding: 7px 11px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #168C70 !important;

  font-size: 10px;
  font-weight: 800;

  text-decoration: none !important;

  transition:
    background .2s ease,
    color .2s ease;
}


.cm-activity-actions > a:hover {
  background: #DDECE2;

  color: #104E45 !important;
}


/* ==========================================================
   WITHDRAW CLAIM BUTTON
========================================================== */

.cm-withdraw-btn {
  min-height: 32px;

  padding: 7px 13px;

  border: 1px solid #D2DED8;
  border-radius: 999px;

  background: #FFFFFF;

  color: #15564B;

  font-family: inherit;

  font-size: 10px;
  font-weight: 800;

  cursor: pointer;

  transition:
    border-color .2s ease,
    background .2s ease,
    color .2s ease;
}


.cm-withdraw-btn:hover {
  border-color: #15564B;

  background: #EDF5E9;

  color: #104E45;
}


.cm-withdraw-btn:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* ==========================================================
   WITHDRAWN CLAIM NOTE
========================================================== */

.cm-withdrawn-note {
  margin-top: 12px;

  padding: 10px 12px;

  border: 1px solid #D2DED8;
  border-radius: 11px;

  background: #F5F8F3;

  color: #506267;

  font-size: 10px;
  font-weight: 700;
}


/* ==========================================================
   WITHDRAW MODAL OVERLAY
========================================================== */

.cm-withdraw-overlay {
  position: fixed;

  inset: 0;

  z-index: 99999;

  padding: 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  box-sizing: border-box;

  background:
    rgba(
      16,
      46,
      52,
      .48
    );

  backdrop-filter:
    blur(3px);
}


/* ==========================================================
   WITHDRAW MODAL
========================================================== */

.cm-withdraw-modal {
  width: 100%;
  max-width: 470px;

  max-height: calc(100vh - 40px);

  overflow-y: auto;

  padding: 28px;

  box-sizing: border-box;

  border: 1px solid #D2DED8;
  border-radius: 23px;

  background: #FBF8EF;

  box-shadow:
    0 22px 65px
    rgba(
      16,
      46,
      52,
      .22
    );
}


/* ==========================================================
   MODAL ICON
========================================================== */

.cm-withdraw-icon {
  width: 48px;
  height: 48px;

  margin-bottom: 15px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #FBEAE7;

  color: #A44832;

  font-size: 19px;
  font-weight: 900;
}


/* ==========================================================
   MODAL TEXT
========================================================== */

.cm-withdraw-modal h3 {
  margin:
    0
    0
    9px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 21px;
  font-weight: 700;
}


.cm-withdraw-modal > p {
  margin:
    0
    0
    18px;

  color: #506267;

  font-size: 12px;
  line-height: 1.65;
}


/* ==========================================================
   MATCH SUMMARY
========================================================== */

.cm-withdraw-summary {
  margin-bottom: 20px;

  padding: 12px 14px;

  border: 1px solid #D2DED8;
  border-radius: 13px;

  background: #FFFFFF;
}


.cm-withdraw-summary span {
  display: block;

  margin-bottom: 4px;

  color: #718185;

  font-size: 8px;
  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: .5px;
}


.cm-withdraw-summary strong {
  display: block;

  color: #102E34;

  font-size: 11px;
  font-weight: 800;
}


/* ==========================================================
   REASON
========================================================== */

.cm-withdraw-modal label {
  display: block;

  margin-bottom: 7px;

  color: #102E34;

  font-size: 10px;
  font-weight: 800;
}


.cm-withdraw-modal label span {
  color: #718185;

  font-weight: 500;
}


.cm-withdraw-modal textarea {
  width: 100%;
  min-height: 95px;

  padding: 12px 13px;

  box-sizing: border-box;

  resize: vertical;

  outline: none;

  border: 1px solid #D2DED8;
  border-radius: 13px;

  background: #FFFFFF;

  color: #102E34;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  font-size: 11px;
  line-height: 1.5;

  transition:
    border-color .2s ease,
    box-shadow .2s ease;
}


.cm-withdraw-modal textarea:focus {
  border-color: #249D78;

  box-shadow:
    0 0 0 3px
    rgba(
      36,
      157,
      120,
      .10
    );
}


.cm-withdraw-modal textarea::placeholder {
  color: #9AA5A7;
}


/* ==========================================================
   CHARACTER COUNT
========================================================== */

.cm-withdraw-character-count {
  margin-top: 5px;

  color: #849194;

  font-size: 8px;

  text-align: right;
}


/* ==========================================================
   MODAL ACTIONS
========================================================== */

.cm-withdraw-actions {
  margin-top: 21px;

  display: flex;
  justify-content: flex-end;

  gap: 10px;
}


.cm-withdraw-cancel,
.cm-withdraw-confirm {
  min-width: 130px;

  padding: 10px 16px;

  border-radius: 999px;

  font-family: inherit;

  font-size: 10px;
  font-weight: 800;

  cursor: pointer;

  transition:
    background .2s ease,
    border-color .2s ease,
    color .2s ease,
    opacity .2s ease;
}


/* CANCEL */

.cm-withdraw-cancel {
  border: 1px solid #D2DED8;

  background: #FFFFFF;

  color: #506267;
}


.cm-withdraw-cancel:hover {
  border-color: #B7CBC1;

  background: #EDF5E9;

  color: #104E45;
}


/* CONFIRM */

.cm-withdraw-confirm {
  border: 1px solid #104E45;

  background: #104E45;

  color: #FFFFFF;
}


.cm-withdraw-confirm:hover {
  border-color: #15564B;

  background: #15564B;
}


.cm-withdraw-cancel:disabled,
.cm-withdraw-confirm:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* ==========================================================
   WITHDRAWAL RESPONSIVE
========================================================== */

@media (max-width: 560px) {

  .cm-withdraw-overlay {
    padding: 14px;
  }


  .cm-withdraw-modal {
    padding: 22px 18px;

    border-radius: 19px;
  }


  .cm-withdraw-modal h3 {
    font-size: 19px;
  }


  .cm-withdraw-actions {
    flex-direction: column-reverse;
  }


  .cm-withdraw-cancel,
  .cm-withdraw-confirm {
    width: 100%;
  }


  .cm-activity-actions {
    align-items: stretch;

    flex-direction: column;
  }


  .cm-activity-actions > a,
  .cm-withdraw-btn {
    width: 100%;

    box-sizing: border-box;

    justify-content: center;

    text-align: center;
  }

}

sp_widget.script:
(function() {



    /* ======================================================

       TABLES

    ====================================================== */



    var ITEM_TABLE =

        'x_snc_campusmatch_campusmatch_item';



    var MATCH_TABLE =

        'x_snc_campusmatch_campusmatch_match';



    var CLAIM_TABLE =

        'x_snc_campusmatch_campusmatch_claim';





    /* ======================================================

       MATCH FIELD VALUES

    ====================================================== */



    var MATCH_WITHDRAWN =

        'withdrawn';



    var MATCH_ACTIVE =

        'active';



    /*

     * Actual Match rejected/no-match choice value

     * in CampusMatch.

     */



    var MATCH_REJECTED =

        'no_match';





    /* ======================================================

       CLAIM FIELD VALUES

       IMPORTANT:

       Your newly-created Withdrawn choice value is lowercase:

       withdrawn

       Existing values such as Submitted / Approved /

       Rejected may use capitalization in your table.

       Therefore comparisons below are normalized.

    ====================================================== */



    var CLAIM_WITHDRAWN =

        'withdrawn';





    /* ======================================================

       OUTPUT

    ====================================================== */



    data.success =

        false;



    data.message =

        '';



    data.reports =

        [];



    data.activity =

        [];



    data.stats = {



        lost: 0,



        found: 0,



        matched: 0,



        resolved: 0



    };





    /* ======================================================

       CURRENT USER

    ====================================================== */



    var access =

        new CampusMatchAccess();



    var userId =

        access.getUserId();



    data.userName =

        gs.getUserDisplayName() ||

        'Student';



    data.firstName =

        data.userName;



    data.initials =

        '';



    if (

        data.userName

    ) {



        var parts =

            data.userName

                .trim()

                .split(/\s+/);



        data.firstName =

            parts[0];



        if (

            parts.length === 1

        ) {



            data.initials =

                parts[0]

                    .substring(

                        0,

                        2

                    )

                    .toUpperCase();



        }

        else {



            data.initials =

                (

                    parts[0].charAt(0) +

                    parts[

                        parts.length - 1

                    ].charAt(0)

                )

                .toUpperCase();



        }



    }





    /* ======================================================

       HELPERS

    ====================================================== */



    /*

     * Some CampusMatch Claim fields were created at

     * different stages of development.

     *

     * This helper safely finds the actual field that exists.

     */



    function firstValidField(

        gr,

        candidates

    ) {



        if (

            !gr ||

            !candidates

        ) {



            return '';



        }



        for (

            var i = 0;

            i < candidates.length;

            i++

        ) {



            if (

                gr.isValidField(

                    candidates[i]

                )

            ) {



                return candidates[i];



            }



        }



        return '';



    }





    function normalize(

        value

    ) {



        return (

            value ||

            ''

        )

        .toString()

        .toLowerCase()

        .trim();



    }





    function loadItem(

        sysId

    ) {



        if (

            !sysId

        ) {



            return null;



        }



        var gr =

            new GlideRecord(

                ITEM_TABLE

            );



        if (

            !gr.get(

                sysId

            )

        ) {



            return null;



        }



        return gr;



    }





    function loadMatch(

        sysId

    ) {



        if (

            !sysId

        ) {



            return null;



        }



        var gr =

            new GlideRecord(

                MATCH_TABLE

            );



        if (

            !gr.get(

                sysId

            )

        ) {



            return null;



        }



        return gr;



    }





    /* ======================================================

       CLAIM FIELD HELPERS

    ====================================================== */



    function claimMatchField(

        gr

    ) {



        return firstValidField(

            gr,

            [

                'match',

                'u_match'

            ]

        );



    }





    function claimItemField(

        gr

    ) {



        return firstValidField(

            gr,

            [

                'item',

                'u_item'

            ]

        );



    }





    function claimantField(

        gr

    ) {



        return firstValidField(

            gr,

            [

                'claimant',

                'u_claimant'

            ]

        );



    }





    function claimStatusField(

        gr

    ) {



        return firstValidField(

            gr,

            [

                'claim_status',

                'u_claim_status'

            ]

        );



    }





    function handoverCompletedField(

        gr

    ) {



        return firstValidField(

            gr,

            [

                'handover_completed',

                'u_handover_completed'

            ]

        );



    }





    /* ======================================================

       CHECK WHETHER CLAIM BELONGS TO CURRENT USER

    ====================================================== */



    function userOwnsClaim(

        claim,

        relatedLostItemId

    ) {



        if (

            !claim

        ) {



            return false;



        }



        /*

         * Preferred check:

         * Claim.Claimant = current user

         */



        var claimant =

            claimantField(

                claim

            );



        if (

            claimant

        ) {



            var claimantId =

                claim.getValue(

                    claimant

                );



            if (

                claimantId

            ) {



                return (

                    claimantId ===

                    userId

                );



            }



        }





        /*

         * Safe fallback:

         *

         * CampusMatch claims belong to the Lost reporter.

         *

         * If older Claim records do not contain a claimant

         * field, verify ownership using Match.Lost Item.

         */



        if (

            relatedLostItemId

        ) {



            var lostItem =

                loadItem(

                    relatedLostItemId

                );



            if (

                lostItem

            ) {



                return (

                    lostItem.getValue(

                        'reporter'

                    ) ===

                    userId

                );



            }



        }



        return false;



    }





    /* ======================================================

       CAN CLAIM BE WITHDRAWN?

    ====================================================== */



    function canWithdrawClaim(

        claim,

        lostItemId

    ) {



        if (

            !claim ||

            !userOwnsClaim(

                claim,

                lostItemId

            )

        ) {



            return false;



        }



        var statusField =

            claimStatusField(

                claim

            );



        if (

            !statusField

        ) {



            return false;



        }



        var status =

            normalize(

                claim.getValue(

                    statusField

                )

            );



        /*

         * CLOSED CLAIMS

         */



        if (

            status === 'withdrawn' ||

            status === 'rejected' ||

            status === 'cancelled' ||

            status === 'canceled'

        ) {



            return false;



        }





        /*

         * PHYSICAL HANDOVER COMPLETE

         *

         * Once the student has actually collected the item,

         * Unclaim is no longer allowed.

         */



        var handoverField =

            handoverCompletedField(

                claim

            );



        if (

            handoverField

        ) {



            var completed =

                normalize(

                    claim.getValue(

                        handoverField

                    )

                );



            if (

                completed === '1' ||

                completed === 'true'

            ) {



                return false;



            }



        }



        return true;



    }





    /* ======================================================

       FIND CURRENT USER'S CLAIM FOR A MATCH

    ====================================================== */



    function findUserClaimForMatch(

        matchId,

        lostItemId

    ) {



        if (

            !matchId

        ) {



            return null;



        }



        var claim =

            new GlideRecord(

                CLAIM_TABLE

            );



        var matchField =

            claimMatchField(

                claim

            );



        if (

            !matchField

        ) {



            return null;



        }



        claim.addQuery(

            matchField,

            matchId

        );



        claim.orderByDesc(

            'sys_created_on'

        );



        claim.query();



        while (

            claim.next()

        ) {



            if (

                userOwnsClaim(

                    claim,

                    lostItemId

                )

            ) {



                return claim;



            }



        }



        return null;



    }





    /* ======================================================

       SET ITEM BACK TO ACTIVE

       IMPORTANT:

       We only change Item Status.

       Security Desk custody fields are NOT cleared.

    ====================================================== */



    function reactivateItem(

        itemId

    ) {



        if (

            !itemId

        ) {



            return;



        }



        var item =

            loadItem(

                itemId

            );



        if (

            !item

        ) {



            return;



        }



        if (

            item.isValidField(

                'status'

            )

        ) {



            item.setValue(

                'status',

                'active'

            );



            item.update();



        }



    }





    /* ======================================================

       REOPEN COMPETING MATCHES

       Only reopen Matches that were rejected specifically

       because another candidate was selected.

       Staff-rejected Matches MUST stay rejected.

    ====================================================== */



    function reopenCompetingMatches(

        selectedMatch

    ) {



        if (

            !selectedMatch

        ) {



            return;



        }



        var foundItemId =

            selectedMatch.getValue(

                'found_item'

            );



        if (

            !foundItemId

        ) {



            return;



        }



        /*

         * Decision Reason was added specifically so we can

         * distinguish:

         *

         * competing_candidate

         * from

         * staff_rejected

         */



        if (

            !selectedMatch.isValidField(

                'decision_reason'

            )

        ) {



            /*

             * SAFETY:

             *

             * If Decision Reason does not exist,

             * DO NOT blindly reopen rejected Matches.

             */



            return;



        }



        var competitor =

            new GlideRecord(

                MATCH_TABLE

            );



        competitor.addQuery(

            'found_item',

            foundItemId

        );



        competitor.addQuery(

            'sys_id',

            '!=',

            selectedMatch.getUniqueValue()

        );



        competitor.addQuery(

            'status',

            MATCH_REJECTED

        );



        competitor.addQuery(

            'decision_reason',

            'competing_candidate'

        );



        /*

         * Only Student-visible Potential / Strong matches.

         */



        competitor.addQuery(

            'overall_score',

            '>=',

            65

        );



        competitor.query();



        while (

            competitor.next()

        ) {



            competitor.setValue(

                'status',

                MATCH_ACTIVE

            );



            competitor.setValue(

                'decision_reason',

                ''

            );



            if (

                competitor.isValidField(

                    'reviewed_by'

                )

            ) {



                competitor.setValue(

                    'reviewed_by',

                    ''

                );



            }



            if (

                competitor.isValidField(

                    'reviewed_on'

                )

            ) {



                competitor.setValue(

                    'reviewed_on',

                    ''

                );



            }



            competitor.update();



        }



    }





    /* ======================================================

       WITHDRAW CLAIM ACTION

    ====================================================== */



    if (

        input &&

        input.action ===

            'withdrawClaim'

    ) {



        var requestedClaimId =

            (

                input.claim_id ||

                ''

            )

            .toString()

            .trim();



        var withdrawalReason =

            (

                input.reason ||

                ''

            )

            .toString()

            .substring(

                0,

                500

            );



        if (

            !requestedClaimId

        ) {



            data.success =

                false;



            data.message =

                'Claim could not be identified.';



            return;



        }





        /* ==================================================

           LOAD CLAIM

        ================================================== */



        var withdrawClaim =

            new GlideRecord(

                CLAIM_TABLE

            );



        if (

            !withdrawClaim.get(

                requestedClaimId

            )

        ) {



            data.success =

                false;



            data.message =

                'Claim record could not be found.';



            return;



        }





        /* ==================================================

           LOAD RELATED MATCH

        ================================================== */



        var withdrawMatchField =

            claimMatchField(

                withdrawClaim

            );



        if (

            !withdrawMatchField

        ) {



            data.success =

                false;



            data.message =

                'The Claim is not linked to a Match.';



            return;



        }



        var relatedMatchId =

            withdrawClaim.getValue(

                withdrawMatchField

            );



        if (

            !relatedMatchId

        ) {



            data.success =

                false;



            data.message =

                'The Claim is not linked to a Match.';



            return;



        }



        var relatedMatch =

            loadMatch(

                relatedMatchId

            );



        if (

            !relatedMatch

        ) {



            data.success =

                false;



            data.message =

                'The related Match could not be found.';



            return;



        }



        var relatedLostItemId =

            relatedMatch.getValue(

                'lost_item'

            );



        var relatedFoundItemId =

            relatedMatch.getValue(

                'found_item'

            );





        /* ==================================================

           SECURITY:

           CLAIM MUST BELONG TO CURRENT USER

        ================================================== */



        if (

            !userOwnsClaim(

                withdrawClaim,

                relatedLostItemId

            )

        ) {



            data.success =

                false;



            data.message =

                'You are not allowed to withdraw this claim.';



            return;



        }





        /* ==================================================

           CLAIM STATUS VALIDATION

        ================================================== */



        var statusField =

            claimStatusField(

                withdrawClaim

            );



        if (

            !statusField

        ) {



            data.success =

                false;



            data.message =

                'Claim Status field could not be found.';



            return;



        }



        var existingClaimStatus =

            normalize(

                withdrawClaim.getValue(

                    statusField

                )

            );



        if (

            existingClaimStatus ===

                'withdrawn'

        ) {



            data.success =

                false;



            data.message =

                'This claim has already been withdrawn.';



            return;



        }



        if (

            existingClaimStatus ===

                'rejected' ||

            existingClaimStatus ===

                'cancelled'

        ) {



            data.success =

                false;



            data.message =

                'This claim is already closed and cannot be withdrawn.';



            return;



        }





        /* ==================================================

           HANDOVER VALIDATION

        ================================================== */



        var handoverField =

            handoverCompletedField(

                withdrawClaim

            );



        if (

            handoverField

        ) {



            var handoverCompleted =

                normalize(

                    withdrawClaim.getValue(

                        handoverField

                    )

                );



            if (

                handoverCompleted ===

                    '1' ||

                handoverCompleted ===

                    'true'

            ) {



                data.success =

                    false;



                data.message =

                    'This claim cannot be withdrawn because the item has already been collected.';



                return;



            }



        }





        /* ==================================================

           UPDATE CLAIM

        ================================================== */



        withdrawClaim.setValue(

            statusField,

            CLAIM_WITHDRAWN

        );



        if (

            withdrawClaim.isValidField(

                'withdrawn_by'

            )

        ) {



            withdrawClaim.setValue(

                'withdrawn_by',

                userId

            );



        }



        if (

            withdrawClaim.isValidField(

                'withdrawn_on'

            )

        ) {



            withdrawClaim.setValue(

                'withdrawn_on',

                new GlideDateTime()

                    .getValue()

            );



        }



        if (

            withdrawClaim.isValidField(

                'withdrawal_reason'

            )

        ) {



            withdrawClaim.setValue(

                'withdrawal_reason',

                withdrawalReason

            );



        }



        withdrawClaim.update();





        /* ==================================================

           UPDATE SELECTED MATCH

        ================================================== */



        if (

            relatedMatch.isValidField(

                'status'

            )

        ) {



            relatedMatch.setValue(

                'status',

                MATCH_WITHDRAWN

            );



        }



        if (

            relatedMatch.isValidField(

                'decision_reason'

            )

        ) {



            relatedMatch.setValue(

                'decision_reason',

                'claim_withdrawn'

            );



        }



        relatedMatch.update();





        /* ==================================================

           REACTIVATE LOST + FOUND ITEMS

        ================================================== */



        reactivateItem(

            relatedLostItemId

        );



        reactivateItem(

            relatedFoundItemId

        );





        /* ==================================================

           REOPEN ELIGIBLE COMPETING MATCHES

        ================================================== */



        reopenCompetingMatches(

            relatedMatch

        );





        /* ==================================================

           SUCCESS

        ================================================== */



        data.success =

            true;



        data.message =

            'Your claim has been withdrawn. CampusMatch will continue looking for another match.';



        return;



    }





    /* ======================================================

       LOAD ONLY CURRENT USER'S ITEMS

       Students must never receive another user's reports.

    ====================================================== */



    var userItemIds =

        [];



    var reportIndex =

        {};



    var item =

        new GlideRecord(

            ITEM_TABLE

        );



    item.addQuery(

        'reporter',

        userId

    );



    item.orderByDesc(

        'sys_created_on'

    );



    item.query();





    while (

        item.next()

    ) {



        var sysId =

            item.getUniqueValue();



        var type =

            normalize(

                item.getValue(

                    'report_type'

                )

            );



        var itemStatus =

            normalize(

                item.getValue(

                    'status'

                )

            );





        /*

         * The reporter may see the original title

         * of THEIR OWN report.

         */



        var title =

            item.getValue(

                'title'

            ) ||



            item.getDisplayValue(

                'public_title'

            ) ||



            (

                type === 'found'

                    ? 'Found Item'

                    : 'Lost Item'

            );





        /* ==================================================

           COUNTS

        ================================================== */



        if (

            type === 'lost'

        ) {



            data.stats.lost++;



        }



        if (

            type === 'found'

        ) {



            data.stats.found++;



        }



        if (

            itemStatus ===

                'resolved'

        ) {



            data.stats.resolved++;



        }





        /* ==================================================

           OWNER ITEM IMAGE

           LOAD CONVERTED USER_IMAGE SAFELY FOR OWNER

           IMPORTANT:
           Do not expose the raw sys_attachment URL to
           the student's browser.

           These Item records are already restricted to
           the current reporter above, so the server can
           read the converted image and return a data URL.

        ================================================== */



        var dashboardImageUrl =

            '';



        var imageAttachment =

            new GlideRecord(

                'sys_attachment'

            );



        imageAttachment.addQuery(

            'table_sys_id',

            sysId

        );



        imageAttachment.addQuery(

            'table_name',

            'ZZ_YY' + ITEM_TABLE

        );



        imageAttachment.addQuery(

            'file_name',

            'image'

        );



        imageAttachment.orderByDesc(

            'sys_created_on'

        );



        imageAttachment.setLimit(

            1

        );



        imageAttachment.query();



        if (

            imageAttachment.next()

        ) {



            try {



                var attachmentApi =

                    new GlideSysAttachment();



                var imageBase64 =

                    attachmentApi.getContentBase64(

                        imageAttachment

                    );



                var imageContentType =

                    imageAttachment.getValue(

                        'content_type'

                    ) ||

                    'image/jpeg';



                if (imageBase64) {



                    dashboardImageUrl =

                        'data:' +

                        imageContentType +

                        ';base64,' +

                        imageBase64;



                }



            }

            catch (imageError) {



                gs.error(

                    'CampusMatch Dashboard image load failed for Item ' +

                    sysId +

                    ': ' +

                    imageError.message

                );



                dashboardImageUrl =

                    '';



            }



        }



        /* ==================================================

           OWNER-SAFE REPORT OBJECT

           HTML USES item.imageUrl

        ================================================== */



        var report = {



            sys_id:

                sysId,



            number:

                item.getDisplayValue(

                    'number'

                ) || '',



            title:

                title,



            imageUrl:

                dashboardImageUrl,



            reportType:

                type,



            category:

                item.getDisplayValue(

                    'category'

                ) || '—',



            locationZone:

                item.getDisplayValue(

                    'location_zone'

                ) || 'Campus',



            reportedDisplay:

                item.getDisplayValue(

                    'reported_date_time'

                ) || '—',



            statusValue:

                itemStatus,



            statusDisplay:

                item.getDisplayValue(

                    'status'

                ) || '—',



            hasMatch:

                false,



            bestMatchId:

                '',



            bestMatchScore:

                0,



            bestMatchLevel:

                ''



        };



        data.reports.push(

            report

        );



        reportIndex[

            sysId

        ] =

            report;



        userItemIds.push(

            sysId

        );



    }





    /* ======================================================

       STOP IF CURRENT USER HAS NO ITEMS

    ====================================================== */



    if (

        userItemIds.length === 0

    ) {



        return;



    }





    /* ======================================================

       LOAD ONLY MATCHES LINKED TO USER'S ITEMS

    ====================================================== */



    var idCSV =

        userItemIds.join(

            ','

        );



    var match =

        new GlideRecord(

            MATCH_TABLE

        );



    var q =

        match.addQuery(

            'lost_item',

            'IN',

            idCSV

        );



    q.addOrCondition(

        'found_item',

        'IN',

        idCSV

    );





    /* ======================================================

       STUDENT-FACING MATCH THRESHOLD

       Only Potential + Strong matches are shown.

       Below 65% stays backend-only.

    ====================================================== */



    match.addQuery(

        'overall_score',

        '>=',

        65

    );



    match.orderByDesc(

        'sys_created_on'

    );



    match.query();





    var matchedItems =

        {};





    /* ======================================================

       PROCESS MATCH RECORDS

    ====================================================== */



    while (

        match.next()

    ) {



        var matchId =

            match.getUniqueValue();



        var lostId =

            match.getValue(

                'lost_item'

            );



        var foundId =

            match.getValue(

                'found_item'

            );





        /* ==================================================

           DEFENSE-IN-DEPTH OWNERSHIP CHECK

        ================================================== */



        if (

            !reportIndex[lostId] &&

            !reportIndex[foundId]

        ) {



            continue;



        }





        /* ==================================================

           SCORE

        ================================================== */



        var score =

            parseFloat(

                match.getValue(

                    'overall_score'

                )

            );



        if (

            isNaN(

                score

            )

        ) {



            score =

                0;



        }



        score =

            Math.round(

                score * 100

            ) / 100;





        /* ==================================================

           SAFETY:

           NEVER EXPOSE LOW-SCORE MATCHES

        ================================================== */



        if (

            score < 65

        ) {



            continue;



        }





        /* ==================================================

           MATCH LEVEL

        ================================================== */



        var levelValue =

            normalize(

                match.getValue(

                    'match_level'

                )

            );



        var levelDisplay =

            match.getDisplayValue(

                'match_level'

            ) ||

            'Match';





        /* ==================================================

           MATCH STATUS

        ================================================== */



        var statusValue =

            normalize(

                match.getValue(

                    'status'

                )

            );



        var statusDisplay =

            match.getDisplayValue(

                'status'

            ) ||

            'Active';





        /* ==================================================

           DETERMINE CURRENT USER'S ITEM

        ================================================== */



        var userItemId =

            '';



        var otherItemId =

            '';



        if (

            reportIndex[

                lostId

            ]

        ) {



            userItemId =

                lostId;



            otherItemId =

                foundId;



        }

        else if (

            reportIndex[

                foundId

            ]

        ) {



            userItemId =

                foundId;



            otherItemId =

                lostId;



        }

        else {



            continue;



        }



        var report =

            reportIndex[

                userItemId

            ];





        /* ==================================================

           OTHER ITEM

           PRIVACY:

           PUBLIC TITLE ONLY.

        ================================================== */



        var otherTitle =

            'Potential Match';



        if (

            otherItemId

        ) {



            var other =

                new GlideRecord(

                    ITEM_TABLE

                );



            if (

                other.get(

                    otherItemId

                )

            ) {



                otherTitle =

                    other.getDisplayValue(

                        'public_title'

                    ) ||

                    'Potential Match';



            }



        }





        /* ==================================================

           LOAD USER'S CLAIM FOR THIS MATCH

        ================================================== */



        var userClaim =

            findUserClaimForMatch(

                matchId,

                lostId

            );



        var claimId =

            '';



        var claimStatusValue =

            '';



        var claimStatusDisplay =

            '';



        var canWithdraw =

            false;



        if (

            userClaim

        ) {



            claimId =

                userClaim.getUniqueValue();



            var userClaimStatusField =

                claimStatusField(

                    userClaim

                );



            if (

                userClaimStatusField

            ) {



                claimStatusValue =

                    normalize(

                        userClaim.getValue(

                            userClaimStatusField

                        )

                    );



                claimStatusDisplay =

                    userClaim.getDisplayValue(

                        userClaimStatusField

                    ) ||

                    '';



            }



            canWithdraw =

                canWithdrawClaim(

                    userClaim,

                    lostId

                );



        }





        /* ==================================================

           WITHDRAWN MATCH

        ================================================== */



        if (

            statusValue ===

                'withdrawn'

        ) {



            data.activity.push({



                matchId:

                    matchId,



                claimId:

                    claimId,



                claimStatusValue:

                    claimStatusValue,



                claimStatusDisplay:

                    claimStatusDisplay,



                canWithdraw:

                    false,



                title:

                    'Claim Withdrawn',



                itemTitle:

                    report.title,



                otherTitle:

                    otherTitle,



                score:

                    score,



                level:

                    levelDisplay,



                status:

                    statusDisplay,



                date:

                    match.getDisplayValue(

                        'sys_updated_on'

                    ) ||

                    match.getDisplayValue(

                        'sys_created_on'

                    ),



                progress:

                    35



            });



            continue;



        }





        /* ==================================================

           IGNORE STAFF-REJECTED / COMPETING REJECTED MATCHES

        ================================================== */



        if (

            statusValue ===

                MATCH_REJECTED ||

            statusValue ===

                'rejected'

        ) {



            continue;



        }





        /* ==================================================

           ACTIVE MATCH:

           MARK USER'S REPORT AS MATCHED

        ================================================== */



        matchedItems[

            userItemId

        ] =

            true;



        report.hasMatch =

            true;





        /* ==================================================

           BEST MATCH

        ================================================== */



        if (

            !report.bestMatchId ||

            score >

                report.bestMatchScore

        ) {



            report.bestMatchId =

                matchId;



            report.bestMatchScore =

                score;



            report.bestMatchLevel =

                levelDisplay;



        }





        /* ==================================================

           ACTIVITY TITLE / PROGRESS

        ================================================== */



        var activityTitle =

            'Potential Match Found';



        var progress =

            55;





        /*

         * CLAIM-BASED ACTIVITY HAS PRIORITY

         */



        if (

            claimStatusValue ===

                'approved'

        ) {



            activityTitle =

                'Claim Approved';



            progress =

                90;



        }

        else if (

            claimStatusValue ===

                'under review' ||

            claimStatusValue ===

                'under_review'

        ) {



            activityTitle =

                'Claim Under Review';



            progress =

                75;



        }

        else if (

            claimStatusValue ===

                'submitted'

        ) {



            activityTitle =

                'Ownership Claim Submitted';



            progress =

                70;



        }

        else if (

            statusValue ===

                'resolved'

        ) {



            activityTitle =

                'Match Resolved';



            progress =

                100;



        }

        else if (

            statusValue ===

                'confirmed'

        ) {



            activityTitle =

                'Match Confirmed';



            progress =

                80;



        }

        else if (

            statusValue ===

                'under_review'

        ) {



            activityTitle =

                'Match Under Review';



            progress =

                65;



        }

        else if (

            levelValue ===

                'strong'

        ) {



            activityTitle =

                'Strong Match Found';



            progress =

                60;



        }





        /* ==================================================

           PRIVACY-SAFE ACTIVITY OBJECT

        ================================================== */



        data.activity.push({



            matchId:

                matchId,



            claimId:

                claimId,



            claimStatusValue:

                claimStatusValue,



            claimStatusDisplay:

                claimStatusDisplay,



            canWithdraw:

                canWithdraw,



            title:

                activityTitle,



            itemTitle:

                report.title,



            otherTitle:

                otherTitle,



            score:

                score,



            level:

                levelDisplay,



            status:

                statusDisplay,



            date:

                match.getDisplayValue(

                    'sys_created_on'

                ),



            progress:

                progress



        });



    }





    /* ======================================================

       MATCHED COUNT

    ====================================================== */



    for (

        var matchedId

        in matchedItems

    ) {



        if (

            matchedItems

                .hasOwnProperty(

                    matchedId

                )

        ) {



            data.stats.matched++;



        }



    }





    /* ======================================================

       LIMIT ACTIVITY

    ====================================================== */



    if (

        data.activity.length >

            15

    ) {



        data.activity =

            data.activity.slice(

                0,

                15

            );



    }





})();
